# Standard library
import uuid

# Third-party
from sqlalchemy import Boolean, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefCompendiumType(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_compendium_type"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a POI category such as Summit, Hut, Lake, or Pass."
        ),
    )
    is_collectable: Mapped[bool] = mapped_column(
        Boolean,
        nullable=False,
        server_default="true",
        comment=(
            "Whether POIs of this type generate visits and cards when a "
            "track passes nearby. False for transport and parking types."
        ),
    )
